sys_script_include.script:
function GetStoreAppStatus(aWhitelist)
{
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var GetValue = x_snc_devtools.GetValue;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var Clone = x_snc_devtools.Clone;
	var IsValidSysId = x_snc_devtools.IsValidSysId;
	var IsValidAppName = x_snc_devtools.IsValidAppName;
	var IsValidScope = x_snc_devtools.IsValidScope;

	aWhitelist = GetArrayValue(aWhitelist);

	if (aWhitelist.length == 0)
	{
		return false;
	}

	var strQuery = '';

	if (aWhitelist.length == 1 && GetValue(aWhitelist,0) == 'all')
	{
		strQuery = '';
	}
	else
	{
		var aSysIds = [];
		var aScopes = [];
		var aNames = [];
		for (nWhitelist = 0; nWhitelist < aWhitelist.length; nWhitelist++)
		{
			var strWhitelist = aWhitelist[nWhitelist];
			if (IsValidSysId(strWhitelist) == true)
			{
				aSysIds.push(strWhitelist);
			}
			else if (IsValidScope(strWhitelist) == true)
			{
				aScopes.push(strWhitelist);				
			}
			else if (IsValidAppName(strWhitelist) == true)
			{
				aNames.push(strWhitelist);
			}
			else
			{
				return false;
			}			
		}
		if (aSysIds.length > 0)
		{
			strQuery += 'sys_idIN' + GetStringValue(aSysIds);
		}	
		if (aScopes.length > 0)
		{
			if (strQuery != '')
			{
				strQuery += '^OR';
			}
			strQuery += 'scopeIN' + GetStringValue(aScopes);
		}		
		if (aNames.length > 0)
		{
			if (strQuery != '')
			{
				strQuery += '^OR';
			}
			strQuery += 'nameIN' + GetStringValue(aNames);
		}		
	}

	var aStoreApps = [];

	var grStoreApp = new GlideRecord('sys_store_app');
	grStoreApp.addEncodedQuery(strQuery);
	grStoreApp.query();
	while (grStoreApp.next())
	{
		var store_app = Clone(grStoreApp);

		delete store_app.sys_meta;
		delete store_app.sys_mod_count;
		delete store_app.sys_tags;

		aStoreApps.push(store_app);
	}

	return aStoreApps;
}
